import { Star, Heart, ShoppingCart } from "lucide-react"
import Image from "next/image"

export interface Product {
  id: string
  name: string
  category: { name: string } | null // Supabase join
  price: number
  sale_price?: number | null
  rating?: number
  reviews?: number
  images: string[]
  is_new?: boolean
}

interface ProductCarouselProps {
  title: string
  products: Product[]
  isNew?: boolean
}

export default function ProductCarousel({ title, products, isNew = false }: ProductCarouselProps) {
  return (
    <section className="max-w-7xl mx-auto px-4 py-16 md:py-20">
      <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-12 text-balance">{title}</h2>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
        {products.map((product) => (
          <div
            key={product.id}
            className="rounded-xl bg-card/40 border border-white/5 overflow-hidden hover:shadow-2xl hover:shadow-primary/10 hover:border-primary/30 transition-all duration-300 group"
          >
            {/* Image Container */}
            <div className="relative bg-secondary/30 p-8 h-64 flex items-center justify-center overflow-hidden group-hover:bg-secondary/50 transition-colors">
              {product.images?.[0] ? (
                <div className="relative w-full h-full group-hover:scale-110 group-hover:-rotate-3 transition-transform duration-500">
                  <Image
                    src={product.images[0]}
                    alt={product.name}
                    fill
                    className="object-contain"
                  />
                </div>
              ) : (
                <div className="text-4xl">🧸</div>
              )}

              {(isNew || product.is_new) && (
                <span className="absolute top-3 left-3 bg-primary text-primary-foreground text-[10px] font-bold px-3 py-1 uppercase tracking-widest rounded-full shadow-lg">
                  New Arrival
                </span>
              )}

              <button className="absolute top-3 right-3 p-2.5 bg-background/80 backdrop-blur-md rounded-full text-muted-foreground hover:text-red-500 hover:bg-background transition-all opacity-0 translate-y-2 group-hover:opacity-100 group-hover:translate-y-0">
                <Heart className="w-4 h-4" />
              </button>
            </div>

            {/* Product Details */}
            <div className="p-5">
              <div className="flex justify-between items-start mb-2">
                <span className="text-[10px] uppercase font-bold text-primary tracking-widest">
                  {product.category?.name || "Toy"}
                </span>
                <div className="flex items-center gap-1">
                  <Star className="w-3.5 h-3.5 fill-yellow-500 text-yellow-500" />
                  <span className="text-xs font-semibold text-muted-foreground">{product.rating || 4.5}</span>
                </div>
              </div>

              <h3 className="font-bold text-foreground text-base mb-2 line-clamp-1 group-hover:text-primary transition-colors">{product.name}</h3>

              {/* Price */}
              <div className="flex items-baseline gap-2 mb-4">
                <span className="text-lg font-black text-foreground">₹{product.price}</span>
                {product.sale_price && product.sale_price > product.price && (
                  <span className="text-sm text-muted-foreground line-through decoration-primary/50">₹{product.sale_price}</span>
                )}
              </div>

              {/* Actions */}
              <button className="w-full bg-primary text-primary-foreground font-bold text-sm py-2.5 rounded-lg hover:bg-primary/90 hover:shadow-lg hover:shadow-primary/25 transition-all flex items-center justify-center gap-2 group/btn">
                <ShoppingCart className="w-4 h-4 group-hover/btn:animate-bounce" />
                <span>Add to Cart</span>
              </button>
            </div>
          </div>
        ))}
      </div>
    </section>
  )
}

