import Link from "next/link"
import Image from "next/image"

interface Category {
  id: string
  name: string
  slug: string
  image_url?: string | null
}

export default function CategoriesSection({ categories }: { categories: Category[] }) {
  return (
    <section className="max-w-7xl mx-auto px-4 py-16 md:py-20">
      <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-12 text-balance">Shop by Category</h2>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
        {categories.map((category) => (
          <Link
            key={category.id}
            href={`/category/${category.slug}`}
            className="group block"
          >
            <div
              className="rounded-xl bg-card/40 backdrop-blur-sm border border-white/5 p-8 hover:bg-card/60 hover:border-primary/50 transition-all duration-300 group cursor-pointer relative overflow-hidden h-full flex flex-col justify-between"
            >
              <div className="absolute top-0 right-0 w-20 h-20 bg-primary/10 blur-2xl -mr-10 -mt-10 rounded-full group-hover:bg-primary/20 transition-all"></div>

              <div className="flex items-start justify-between mb-4 relative z-10">
                {/* Icon or Image */}
                {category.image_url ? (
                  <div className="relative w-16 h-16 rounded-full overflow-hidden border border-border group-hover:scale-110 transition-transform">
                    <Image src={category.image_url} alt={category.name} fill className="object-cover" />
                  </div>
                ) : (
                  <div className="text-5xl group-hover:scale-110 transition-transform duration-300">🧸</div>
                )}

                <div className="text-2xl text-primary opacity-0 -translate-x-4 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-300">→</div>
              </div>

              <div>
                <h3 className="text-xl font-bold text-foreground mb-2">{category.name}</h3>
                <p className="text-sm text-muted-foreground mb-4">Explore collection</p>
                <span
                  className="text-primary font-bold text-sm hover:text-primary/80 transition-colors uppercase tracking-wider"
                >
                  View products
                </span>
              </div>
            </div>
          </Link>
        ))}

        {categories.length === 0 && (
          <div className="col-span-full text-center text-muted-foreground py-10">
            No categories found.
          </div>
        )}
      </div>
    </section>
  )
}
